 VALUES(session,st,cart,attempt,method,profile,'paytr_iframe','test',1,1,'sha256:'||repeat('b',64),'sf:'||session,oid,gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),1,repeat('c',64),'TRY',11000,500,0,11500,'{"contact":{"firstName":"VAT","lastName":"Fixture","email":"vat-hosted@example.test","phone":"+905551112233"},"shippingAddress":{"line1":"Fixture street","city":"Istanbul","country":"TR"}}',jsonb_build_array(jsonb_build_object('productId',pd,'variantId',v,'title','VAT Hosted','variantTitle','Default','quantity',1,'unitPriceCents',11000,'lineTotalCents',11000,'payableCents',11000,'stockTracked',false)),'active','created',t+interval '15 minutes',1,'payment-session-key',repeat('d',64),t+interval '15 minutes','receipt-key',repeat('e',64),t+interval '1 day','customer-key',repeat('f',64),t+interval '30 days',t,t);
